import{_ as t,o as a,c as i,a2 as r}from"./chunks/framework.yFlg5W3A.js";const h=JSON.parse('{"title":"Project Pitch: AstroCare","description":"","frontmatter":{},"headers":[],"relativePath":"00b-project-pitch.md","filePath":"00b-project-pitch.md"}'),o={name:"00b-project-pitch.md"};function n(s,e,c,l,d,p){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="project-pitch-astrocare" tabindex="-1">Project Pitch: AstroCare <a class="header-anchor" href="#project-pitch-astrocare" aria-label="Permalink to &quot;Project Pitch: AstroCare&quot;">​</a></h1><h2 id="_30-second-elevator-pitch" tabindex="-1">30-Second Elevator Pitch <a class="header-anchor" href="#_30-second-elevator-pitch" aria-label="Permalink to &quot;30-Second Elevator Pitch&quot;">​</a></h2><p>&quot;I built <strong>AstroCare</strong>, a mission-critical space-medicine decision-support platform designed for deep-space Mars missions where one-way communication latency to Earth reaches 24 minutes. Built with TypeScript, Express 5, MongoDB Time-Series, and Redis Streams, it ingests multi-lead bio-telemetry with real-time signal quality filtering, fuses alerts to prevent alarm fatigue, runs an ML sidecar predicting cardiovascular decompensation 30 minutes in advance, and provides delay-tolerant store-and-forward synchronization with Earth Mission Control.&quot;</p><h2 id="_2-minute-spoken-pitch" tabindex="-1">2-Minute Spoken Pitch <a class="header-anchor" href="#_2-minute-spoken-pitch" aria-label="Permalink to &quot;2-Minute Spoken Pitch&quot;">​</a></h2><p>&quot;When astronauts travel to Mars, real-time medical guidance from Earth is physically impossible due to the speed of light—a radio signal takes between 3 and 22 minutes each way. If an astronaut experiences cardiac arrhythmia or toxic gas inhalation during an extravehicular activity (EVA), waiting for a flight surgeon in Houston to reply would take almost an hour.</p><p>To solve this autonomy crisis, I engineered AstroCare:</p><p>First, our high-throughput ingestion engine in <code>ingestService.ts</code> accepts biometric telemetry—heart rate, SpO2, multi-lead ECG, blood pressure, and core temperature—at over 1,000 readings per second with strict idempotency and HMAC machine authentication.</p><p>Second, bio-sensor telemetry in microgravity is noisy. Our Signal Quality Analyzer in <code>qualityService.ts</code> screens physiological plausibility, filters motion artifacts and sensor spikes, detects flatlines, and applies linear interpolation over transient sensor dropouts before data touches our MongoDB time-series collection.</p><p>Third, our Alert Fusion Engine solves clinical alarm fatigue. Instead of firing 20 overlapping alarms when an astronaut exercises or decompensates, it groups related anomalies, calculates cross-vital confidence scores, and routes single prioritized clinical incidents to the crew medic.</p><p>Fourth, our ML Sidecar runs continuous inference on 15-minute vital trajectories, predicting acute decompensation up to 45 minutes before clinical failure.</p><p>Finally, for Earth communication, our Comms Delay Emulator models orbital geometry, delay-tolerant networking, and planetary blackout buffers. Local crew medics receive instant sub-10ms alerts over Socket.IO, while Earth flight surgeons receive accurately delayed, role-redacted historical replays.&quot;</p>',11)])])}const m=t(o,[["render",n]]);export{h as __pageData,m as default};
